def render(row: tuple) -> str:
    slug, title, definition, example, piege, debutant, expert, question, good, bad = row
    return f"""<!-- à relire -->
# {title}

## Définition
{definition}

## Exemple
{example}

## Pièges fréquents
{piege}

## Version débutant
{debutant}

## Version expert
{expert}

## Quiz
Question: {question}
- A. {good}
- B. {bad}
Réponse: A
"""


def main() -> None:
    OUT.mkdir(parents=True, exist_ok=True)
    for old in OUT.glob("*.md"):
        old.unlink()
    for row in FICHES:
        (OUT / f"{row[0]}.md").write_text(render(row), encoding="utf-8")
    print(f"{len(FICHES)} fiches dans {OUT}")


if __name__ == "__main__":
    main()
